import os
from google.cloud import pubsub_v1

def batch_publish(payload, config=None):
    config = config or {}
    project_id = config.get("project_id") or os.environ.get("GOOGLE_CLOUD_PROJECT")
    topic_name = config.get("topic_name")
    if not project_id or not topic_name:
        raise ValueError("project_id and topic_name are required")
    publisher = pubsub_v1.PublisherClient()
    topic_path = publisher.topic_path(project_id, topic_name)
    futures = []
    for message in payload:
        if isinstance(message, dict):
            data = message.get("data", "")
            if isinstance(data, str):
                data = data.encode("utf-8")
            attrs = message.get("attributes") or {}
        else:
            data = str(message).encode("utf-8")
            attrs = {}
        futures.append(publisher.publish(topic_path, data, **attrs))
    result = [future.result() for future in futures]
    return result
